package com.smartexam.mvp;

import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import com.smartexam.entity.*;import com.smartexam.security.JwtService;import com.smartexam.service.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest @AutoConfigureMockMvc @Transactional class MvpWorkflowIntegrationTest{
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired UsersService users;@Autowired CoursesService courses;@Autowired CourseStudentsService memberships;@Autowired ExamsService exams;@Autowired QuestionsService questions;@Autowired ScoringPointsService points;@Autowired SubmissionsService submissions;@Autowired AnswersService answers;@Autowired JwtService jwt;
 String student,teacher;Long examId,singleId,shortId;
 @BeforeEach void setup(){Users t=users.findByUsername("teacher_demo"),s=users.findByUsername("student_demo_1");teacher=jwt.generate(t);student=jwt.generate(s);Courses c=new Courses();c.setTeacherId(t.getId());c.setCourseName("MVP闭环测试");courses.save(c);CourseStudents cs=new CourseStudents();cs.setCourseId(c.getId());cs.setStudentId(s.getId());cs.setStatus(1);memberships.save(cs);Exams e=new Exams();e.setCourseId(c.getId());e.setTitle("可作答考试");e.setDescription("集成测试");e.setStartTime(LocalDateTime.now().minusMinutes(5));e.setEndTime(LocalDateTime.now().plusMinutes(30));e.setLateEntryMinutes(10);e.setMinSubmitMinutes(0);e.setStatus("PUBLISHED");e.setCreatedBy(t.getId());exams.save(e);examId=e.getId();Questions q=new Questions();q.setExamId(examId);q.setQuestionType("SINGLE_CHOICE");q.setContent("2+2=?");q.setScore(new BigDecimal("5"));q.setOptionsJson("[{\"key\":\"A\",\"text\":\"4\"},{\"key\":\"B\",\"text\":\"3\"},{\"key\":\"C\",\"text\":\"2\"},{\"key\":\"D\",\"text\":\"1\"}]");q.setReferenceAnswer("A");q.setSortOrder(1);questions.save(q);singleId=q.getId();q=new Questions();q.setExamId(examId);q.setQuestionType("SHORT_ANSWER");q.setContent("说明JWT");q.setScore(new BigDecimal("10"));q.setReferenceAnswer("签名令牌");q.setSortOrder(2);questions.save(q);shortId=q.getId();ScoringPoints p=new ScoringPoints();p.setQuestionId(shortId);p.setPointContent("签名");p.setPointScore(new BigDecimal("10"));p.setSortOrder(1);points.save(p);}
 JsonNode call(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder r,Object body,String token,int status)throws Exception{r.header("Authorization","Bearer "+token);if(body!=null)r.contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body));String value=mvc.perform(r).andExpect(status().is(status)).andReturn().getResponse().getContentAsString();return json.readTree(value);}
 @Test void studentCompletesWorkflowWithoutSensitiveFields()throws Exception{JsonNode list=call(get("/api/student/exams"),null,student,200);assertThat(list.toString()).doesNotContain("referenceAnswer","scoringPoints","teacherScore","aiScore","aiReason");JsonNode paper=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data");Long sid=paper.path("submissionId").asLong();assertThat(paper.toString()).doesNotContain("referenceAnswer","scoringPoints","teacherScore","aiScore","aiReason");call(put("/api/student/submissions/"+sid+"/answers/"+singleId),Map.of("answerContent","A"),student,200);call(put("/api/student/submissions/"+sid+"/answers/"+shortId),Map.of("answerContent","JWT由签名保护"),student,200);call(post("/api/student/submissions/"+sid+"/submit"),null,student,200);assertThat(submissions.getById(sid).getStatus()).isEqualTo("SUBMITTED");assertThat(answers.findOne(sid,singleId).getAutoScore()).isEqualByComparingTo("5");call(get("/api/student/submissions/"+sid+"/paper"),null,student,409);call(post("/api/student/submissions/"+sid+"/submit"),null,student,409);call(get("/api/student/results/"+sid),null,student,403);}
 @Test void teacherReviewsAiConfigurationAndPublishes()throws Exception{Long sid=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data").path("submissionId").asLong();call(put("/api/student/submissions/"+sid+"/answers/"+shortId),Map.of("answerContent","签名"),student,200);call(post("/api/student/submissions/"+sid+"/submit"),null,student,200);Answers shortAnswer=answers.findOne(sid,shortId);JsonNode ai=call(post("/api/teacher/grading/answers/"+shortAnswer.getId()+"/ai-grade"),null,teacher,200);assertThat(ai.toString()).contains("AI 阅卷未配置").doesNotContain("SUCCESS");call(put("/api/teacher/grading/answers/"+shortAnswer.getId()+"/review"),Map.of("teacherScore",8,"teacherComment","要点基本完整"),teacher,200);call(put("/api/teacher/grading/submissions/"+sid+"/comment"),Map.of("teacherComment","继续努力"),teacher,200);call(post("/api/teacher/grading/submissions/"+sid+"/publish"),null,teacher,200);JsonNode result=call(get("/api/student/results/"+sid),null,student,200).path("data");assertThat(result.path("totalScore").decimalValue()).isEqualByComparingTo("8");assertThat(result.path("teacherComment").asText()).isEqualTo("继续努力");}
 @Test void entryRulesAndAutoSubmitAreEnforced()throws Exception{Exams e=exams.getById(examId);e.setStartTime(LocalDateTime.now().plusMinutes(2));e.setEndTime(LocalDateTime.now().plusMinutes(10));exams.updateById(e);call(post("/api/student/exams/"+examId+"/enter"),null,student,409);e.setStartTime(LocalDateTime.now().minusMinutes(20));e.setEndTime(LocalDateTime.now().plusMinutes(10));e.setLateEntryMinutes(5);exams.updateById(e);call(post("/api/student/exams/"+examId+"/enter"),null,student,409);e.setLateEntryMinutes(30);exams.updateById(e);Long sid=call(post("/api/student/exams/"+examId+"/enter"),null,student,200).path("data").path("submissionId").asLong();LocalDateTime first=submissions.getById(sid).getFirstEnterTime();call(post("/api/student/exams/"+examId+"/enter"),null,student,200);assertThat(submissions.getById(sid).getFirstEnterTime()).isEqualTo(first);assertThat(submissions.getById(sid).getLastEnterTime()).isAfterOrEqualTo(first);e.setEndTime(LocalDateTime.now().minusSeconds(1));exams.updateById(e);call(get("/api/student/exams/"+examId),null,student,200);assertThat(submissions.getById(sid).getStatus()).isEqualTo("AUTO_SUBMITTED");}
}
